### Advanced Exception Handling
```python
def process_data(data):
    try:
        result = complex_operation(data)
        return result
    except ValueError as e:
        print(f"Value error: {e}")
        return None
    except TypeError as e:
        print(f"Type error: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error: {e}")
        raise  # Re-raise the exception
    finally:
        cleanup_resources()
```

### Custom Exceptions
```python
class ValidationError(Exception):
    """Custom exception for validation errors."""
    def __init__(self, message, field=None):
        self.message = message
        self.field = field
        super().__init__(self.message)

class DatabaseError(Exception):
    """Custom exception for database errors."""
    pass

# Using custom exceptions
def validate_age(age):
    if not isinstance(age, int):
        raise ValidationError("Age must be an integer", "age")
    if age < 0 or age > 150:
        raise ValidationError("Age must be between 0 and 150", "age")
    return age
```

### Exception Chaining
```python
def process_file(filename):
    try:
        with open(filename, 'r') as f:
            return f.read()
    except FileNotFoundError as e:
        raise RuntimeError(f"Could not process {filename}") from e
```

### Understanding Metaclasses
Metaclasses are classes for classes. They allow you to customize class creation.

### Basic Metaclass
```python
class Meta(type):
    def __new__(cls, name, bases, attrs):
        # Modify the class attributes
        attrs['created_by'] = 'metaclass'
        return super().__new__(cls, name, bases, attrs)

class MyClass(metaclass=Meta):
    pass

print(MyClass.created_by)  # 'metaclass'
```

### Metaclass for Validation
```python
class ValidatedMeta(type):
    def __new__(cls, name, bases, attrs):
        # Validate required attributes
        if 'required_field' not in attrs:
            raise TypeError(f"{name} must have 'required_field'")
        return super().__new__(cls, name, bases, attrs)

class ValidClass(metaclass=ValidatedMeta):
    required_field = 'value'
```

### Property Descriptors
```python
class Property:
    def __init__(self, fget=None, fset=None, fdel=None):
        self.fget = fget
        self.fset = fset
        self.fdel = fdel

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        if self.fget is None:
            raise AttributeError("unreadable attribute")
        return self.fget(obj)

    def __set__(self, obj, value):
        if self.fset is None:
            raise AttributeError("can't set attribute")
        self.fset(obj, value)

    def __delete__(self, obj):
        if self.fdel is None:
            raise AttributeError("can't delete attribute")
        self.fdel(obj)

# Using the descriptor
class Circle:
    def __init__(self, radius):
        self._radius = radius

    def get_radius(self):
        return self._radius

    def set_radius(self, value):
        if value < 0:
            raise ValueError("Radius cannot be negative")
        self._radius = value

    radius = Property(get_radius, set_radius)
```

### Using ABCs
```python
from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self):
        pass

    @abstractmethod
    def perimeter(self):
        pass

class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return 3.14159 * self.radius ** 2

    def perimeter(self):
        return 2 * 3.14159 * self.radius

# This would raise an error
# shape = Shape()  # TypeError: Can't instantiate abstract class

# This works
circle = Circle(5)
print(circle.area())
```
